import sys
from collections import defaultdict

def main():
    import sys
    import heapq

    def dijkstra(graph, start, target, max_time):
        pq = [(0, start)]
        visited = set()

        while pq:
            current_time, current_station = heapq.heappop(pq)

            if current_station == target:
                return current_time

            if current_station in visited:
                continue

            visited.add(current_station)

            for next_station, (planned_time, delay) in graph[current_station].items():
                if next_station not in visited:
                    new_time = current_time + planned_time + delay
                    if new_time <= max_time:
                        heapq.heappush(pq, (new_time, next_station))

        return float('inf')

    def find_earliest_start_time(N, M, trains):
        graph = defaultdict(dict)

        for X, S, T, L in trains:
            graph[X][X + 1] = (T - S, L)

        max_time = 1800

        for start_time in range(86400):
            if dijkstra(graph, 1, N, start_time + max_time) > start_time + max_time:
                return start_time

        return "impossible"

    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    M = int(data[index + 1])
    index += 2

    trains = []
    for _ in range(M):
        X = int(data[index])
        S = int(data[index + 1])
        T = int(data[index + 2])
        L = int(data[index + 3])
        trains.append((X, S, T, L))
        index += 4

    result = find_earliest_start_time(N, M, trains)
    print(result)

if __name__ == "__main__":
